@php
$profileData = array_merge(is_array($profile ?? null) ? $profile : [], is_array($snapshot['profile_snapshot'] ?? null) ? $snapshot['profile_snapshot'] : []);
$sectionTitles = $document['section_titles'] ?? [];
$title = str_replace('{name}', (string) $plan->contact_name, (string) ($document['title_template'] ?? 'Plan Alimenticio para {name}'));
$age = $profileData['age'] ?? $plan->age ?? null;
$ageGroup = $age ? (floor(((int)$age) / 10) * 10).'–'.(floor(((int)$age) / 10) * 10 + 9).' años' : 'No registrado';
$goal = $snapshot['goal_label'] ?? $snapshot['goal'] ?? $profileData['goal'] ?? 'Mejora de hábitos';
$activity = $snapshot['activity_label'] ?? $snapshot['activity_level'] ?? $profileData['activity_level'] ?? 'No registrada';
$healthFlags = array_values(array_filter(array_map('strval', (array)($profileData['health_flags'] ?? []))));
$allergies = array_values(array_filter(array_map('strval', (array)($profileData['allergies'] ?? []))));
$bmi = $metrics['bmi'] ?? $profileData['bmi'] ?? null;
$bmiLabel = 'No disponible';
if(is_numeric($bmi)){
  $bmiValue=(float)$bmi;
  $bmiLabel=$bmiValue<18.5?'Bajo peso':($bmiValue<25?'Rango habitual':($bmiValue<30?'Sobrepeso':($bmiValue<35?'Obesidad grado 1':($bmiValue<40?'Obesidad grado 2':'Obesidad grado 3'))));
}
$energy = is_array($snapshot['estimated_energy_range'] ?? null) ? $snapshot['estimated_energy_range'] : null;
$macros = is_array($snapshot['macro_targets'] ?? null) ? $snapshot['macro_targets'] : [];
if(($macros['kcal'] ?? null)===null && $energy){$macros['kcal']=(int)round((((int)$energy['min']+(int)$energy['max'])/2)/10)*10;}
$slots = [
  'BREAKFAST'=>['key'=>'breakfast','label'=>'Desayuno'],
  'SNACK_AM'=>['key'=>'snack_am','label'=>'Colación 1'],
  'LUNCH'=>['key'=>'lunch','label'=>'Comida'],
  'SNACK_PM'=>['key'=>'snack_pm','label'=>'Colación 2'],
  'DINNER'=>['key'=>'dinner','label'=>'Cena'],
];
$usedSlots=[];$weeklyMeals=[];
foreach($items as $item){
  $slot=$item['meal_slot']??''; if(!isset($slots[$slot]))continue;
  $usedSlots[$slot]=true;$day=(int)($item['day_index']??0);
  $weeklyMeals[$day]['day']=$item['day_label']??'';
  $weeklyMeals[$day][$slot]=array_merge((array)($item['snapshot']??[]),['serving_multiplier'=>$item['serving_multiplier']??1]);
}
$visibleSlots=array_filter($slots,fn($v,$k)=>isset($usedSlots[$k]),ARRAY_FILTER_USE_BOTH);
$firstDays=array_filter($weeklyMeals,fn($v,$k)=>(int)$k<=4,ARRAY_FILTER_USE_BOTH);
$lastDays=array_filter($weeklyMeals,fn($v,$k)=>(int)$k>4,ARRAY_FILTER_USE_BOTH);
$alerts=[];
foreach($healthFlags as $flag)$alerts[]='Condición declarada: '.$flag.'.';
foreach($allergies as $allergy)$alerts[]='Restricción declarada: '.$allergy.'.';
if(($snapshot['requires_professional_review']??false)||($plan->requires_professional_review??false))$alerts[]=$snapshot['medical_note']??'Se recomienda revisión profesional antes de modificar cantidades o restricciones.';
if(!$alerts)$alerts[]='No se registraron alertas adicionales; conserva el seguimiento de síntomas, tolerancia y adherencia.';
$goldenRules=(array)($document['golden_rules']??[]);
$benefits=(array)($document['benefit_cards']??[]);
$foodsToLimit=(array)($document['foods_to_limit']??[]);
$cravingSupportItems=(array)($document['craving_support_items']??[]);
$shoppingList=(array)($snapshot['shopping_list']??[]);
$substitutions=(array)($snapshot['substitutions']??[]);
$recipeChunks=array_chunk(array_values($recipes),12);
@endphp

